"use client";

import { useState, useEffect, useRef } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';

/**
 * Navbar
 * ------
 * Fixed top navigation bar with:
 *  - Scroll-driven visibility (appears after VRPortal runway)
 *  - Dynamic light ↔ dark theme transition based on scroll position
 *  - Magnetic pull effect on the Apply CTA
 *  - Scroll-progress strip along the top edge
 *  - Mobile full-screen overlay menu (closes on route change)
 *  - Accessible landmark, aria attributes, and unique IDs
 *
 * NOTE (architecture): Navbar is currently imported inside HeroSection.jsx
 * (teammate's file). The desired end-state is to move the import here into
 * src/app/layout.jsx and remove it from HeroSection. Coordinate with teammate
 * before making that structural change.
 */

export default function Navbar() {
  const [isVisible, setIsVisible]         = useState(false);
  const [isDarkTheme, setIsDarkTheme]     = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [scrollProgress, setScrollProgress]     = useState(0);

  const applyButtonRef       = useRef(null);
  const mobileApplyButtonRef = useRef(null);

  const pathname = usePathname();

  // -------------------------------------------------------------------------
  // Close mobile menu whenever the route changes
  // -------------------------------------------------------------------------
  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [pathname]);

  // -------------------------------------------------------------------------
  // Scroll: visibility, dark-theme trigger, progress bar
  // -------------------------------------------------------------------------
  useEffect(() => {
    const handleScroll = () => {
      const scrollY = window.scrollY;
      const vh      = window.innerHeight;
      const maxScroll = document.documentElement.scrollHeight - vh;

      // Visibility: show after VRPortal runway (1.5 × vh)
      setIsVisible(scrollY >= vh * 1.5 - 60);

      // Theme: dark when entering Portfolio section (3.5 × vh)
      setIsDarkTheme(scrollY >= vh * 3.5 - 80);

      // Progress: 0 → 1 over the total scrollable distance
      setScrollProgress(maxScroll > 0 ? Math.min(scrollY / maxScroll, 1) : 0);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // -------------------------------------------------------------------------
  // Magnetic pull on the Apply CTA button(s)
  // -------------------------------------------------------------------------
  useEffect(() => {
    const applyMagnetic = (buttonEl) => {
      if (!buttonEl) return;
      const RADIUS   = 65;
      const STRENGTH = 0.25;

      const onMove = (e) => {
        const rect = buttonEl.getBoundingClientRect();
        const cx   = rect.left + rect.width  / 2;
        const cy   = rect.top  + rect.height / 2;
        const dx   = e.clientX - cx;
        const dy   = e.clientY - cy;
        if (Math.hypot(dx, dy) < RADIUS) {
          buttonEl.style.transform = `translate(${dx * STRENGTH}px, ${dy * STRENGTH}px)`;
        }
      };

      const onLeave = () => {
        buttonEl.style.transform = 'translate(0px, 0px)';
      };

      window.addEventListener('mousemove', onMove);
      buttonEl.addEventListener('mouseleave', onLeave);

      return () => {
        window.removeEventListener('mousemove', onMove);
        buttonEl.removeEventListener('mouseleave', onLeave);
      };
    };

    const cleanupApply       = applyMagnetic(applyButtonRef.current);
    const cleanupMobileApply = applyMagnetic(mobileApplyButtonRef.current);

    return () => {
      if (cleanupApply)       cleanupApply();
      if (cleanupMobileApply) cleanupMobileApply();
    };
  }, [isVisible, isMobileMenuOpen]);

  // -------------------------------------------------------------------------
  // Data
  // -------------------------------------------------------------------------
  const navLinks = [
    { label: 'About',     href: '#about',     type: 'anchor' },
    { label: 'Portfolio', href: '#portfolio', type: 'anchor' },
    { label: 'Metrics',   href: '#metrics',   type: 'anchor' },
    { label: 'Teams',     href: '/teams',     type: 'route'  },
    { label: 'Contact',   href: '#contact',   type: 'anchor' },
  ];

  // -------------------------------------------------------------------------
  // Theme tokens
  // -------------------------------------------------------------------------
  const navbarTheme = isDarkTheme
    ? 'bg-neutral-950/80 border-white/10 text-white'
    : 'bg-white/80 border-black/5 text-neutral-900';

  const mobileMenuTheme = isDarkTheme
    ? 'bg-neutral-950 text-white border-white/10'
    : 'bg-white text-neutral-900 border-black/5';

  const linkHover = isDarkTheme ? 'hover:text-cyan-400' : 'hover:text-neutral-500';
  const btnTheme  = isDarkTheme
    ? 'bg-white text-black hover:bg-neutral-200'
    : 'bg-black text-white hover:bg-neutral-800';

  const barColor  = isDarkTheme ? 'bg-cyan-400' : 'bg-black';
  const hamColor  = isDarkTheme ? 'bg-white' : 'bg-black';

  // -------------------------------------------------------------------------
  // Link renderer (shared between desktop and mobile)
  // -------------------------------------------------------------------------
  const renderLink = (link, extraClass = '') => {
    const isActive = link.type === 'route' && pathname === link.href;
    const linkClass = [
      'font-mono text-[11px] uppercase tracking-widest transition-colors duration-300',
      linkHover,
      extraClass,
    ].join(' ');

    if (link.type === 'route') {
      return (
        <Link
          key={link.label}
          href={link.href}
          id={`nav-link-${link.label.toLowerCase()}`}
          className={linkClass}
          aria-current={isActive ? 'page' : undefined}
          style={{ letterSpacing: '0.15em' }}
          onClick={() => setIsMobileMenuOpen(false)}
        >
          {link.label}
        </Link>
      );
    }

    return (
      <a
        key={link.label}
        href={link.href}
        id={`nav-link-${link.label.toLowerCase()}`}
        className={linkClass}
        style={{ letterSpacing: '0.15em' }}
        onClick={() => setIsMobileMenuOpen(false)}
      >
        {link.label}
      </a>
    );
  };

  // -------------------------------------------------------------------------
  // Render
  // -------------------------------------------------------------------------
  return (
    <header
      id="site-navbar"
      role="banner"
      className={`fixed top-0 left-0 right-0 z-50 w-full border-b backdrop-blur-md transition-all duration-500 ease-out ${navbarTheme} ${
        isVisible
          ? 'opacity-100 translate-y-0'
          : 'opacity-0 -translate-y-full pointer-events-none'
      }`}
    >
      {/* ── Scroll Progress Strip ──────────────────────────────────────── */}
      <div
        className={`absolute top-0 left-0 h-[2px] ${barColor} transition-all duration-100`}
        style={{ width: `${scrollProgress * 100}%` }}
        role="progressbar"
        aria-valuenow={Math.round(scrollProgress * 100)}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label="Page scroll progress"
      />

      {/* ── Main bar ───────────────────────────────────────────────────── */}
      <div className="max-w-7xl mx-auto px-6 md:px-12 h-20 flex items-center justify-between">

        {/* Brand */}
        <Link
          href="/"
          id="nav-brand"
          className="font-sans font-black tracking-widest uppercase text-xs sm:text-sm select-none"
          style={{ letterSpacing: '0.25em' }}
          aria-label="Intellect Studio — home"
        >
          INTELLECT STUDIO
        </Link>

        {/* Desktop nav */}
        <nav
          id="desktop-nav"
          className="hidden md:flex items-center gap-8"
          aria-label="Primary navigation"
        >
          {navLinks.map((link) => renderLink(link))}
        </nav>

        {/* Desktop CTA */}
        <div className="hidden md:block">
          <a
            ref={applyButtonRef}
            id="nav-apply-cta"
            href="#contact"
            className={`magnetic-btn inline-block font-sans font-bold text-xs tracking-wider uppercase px-6 py-3 transition-colors duration-300 ${btnTheme}`}
            style={{ letterSpacing: '0.08em' }}
          >
            Apply Now →
          </a>
        </div>

        {/* Mobile hamburger */}
        <button
          id="mobile-menu-toggle"
          onClick={() => setIsMobileMenuOpen((prev) => !prev)}
          className="md:hidden flex flex-col justify-center items-center w-8 h-8 gap-1.5 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-current"
          aria-label={isMobileMenuOpen ? 'Close navigation menu' : 'Open navigation menu'}
          aria-expanded={isMobileMenuOpen}
          aria-controls="mobile-nav"
        >
          <span
            className={`w-6 h-0.5 transition-all duration-300 transform ${hamColor} ${
              isMobileMenuOpen ? 'rotate-45 translate-y-2' : ''
            }`}
          />
          <span
            className={`w-6 h-0.5 transition-all duration-300 ${hamColor} ${
              isMobileMenuOpen ? 'opacity-0' : 'opacity-100'
            }`}
          />
          <span
            className={`w-6 h-0.5 transition-all duration-300 transform ${hamColor} ${
              isMobileMenuOpen ? '-rotate-45 -translate-y-2' : ''
            }`}
          />
        </button>
      </div>

      {/* ── Mobile Overlay ─────────────────────────────────────────────── */}
      <div
        id="mobile-nav"
        role="navigation"
        aria-label="Mobile navigation"
        aria-hidden={!isMobileMenuOpen}
        className={`md:hidden fixed top-20 left-0 right-0 bottom-0 z-40 w-full h-[calc(100vh-5rem)] border-t transition-all duration-300 ease-in-out ${mobileMenuTheme} ${
          isMobileMenuOpen
            ? 'opacity-100 translate-y-0 pointer-events-auto'
            : 'opacity-0 -translate-y-4 pointer-events-none'
        }`}
      >
        <div className="flex flex-col items-center justify-center h-full gap-8 px-6 pb-20">
          {navLinks.map((link) =>
            renderLink(link, 'text-base')
          )}
          <a
            ref={mobileApplyButtonRef}
            id="mobile-apply-cta"
            href="#contact"
            onClick={() => setIsMobileMenuOpen(false)}
            className={`magnetic-btn font-sans font-bold text-xs tracking-wider uppercase px-8 py-4 mt-4 transition-colors duration-300 ${btnTheme}`}
            style={{ letterSpacing: '0.1em' }}
          >
            Apply Now →
          </a>
        </div>
      </div>
    </header>
  );
}
